package main

// Messages the launcher shows in the window (errors, download states, model notes) in the interface language
// chosen in the settings: Russian (the text in the code), English, German, Spanish or Chinese. The key is the
// Russian text.

import "sync/atomic"

var uiLang atomic.Value // "ru", "en", "de", "es" or "zh"

func setUILang(l string) { uiLang.Store(l) }

func curLang() string {
	if v, ok := uiLang.Load().(string); ok && v != "" {
		return v
	}
	return "ru"
}

// tr returns the message in the interface language; a message without a translation stays Russian.
func tr(s string) string {
	var m map[string]string
	switch curLang() {
	case "en":
		m = msgEN
	case "de":
		m = msgDE
	case "es":
		m = msgES
	case "zh":
		m = msgZH
	default:
		return s
	}
	if v, ok := m[s]; ok {
		return v
	}
	return s
}

